#[no_mangle]
pub extern "C" fn job_sequencing_with_deadline(v:*const i64,n:usize)->i64{if v.is_null()||n<1||n>65{return -1;}let v=unsafe{std::slice::from_raw_parts(v,n)};let count=v[0];if !(1..=32).contains(&count)||n!=1+2*count as usize{return -1;}let mut jobs=Vec::new();for i in 0..count as usize{let d=v[1+2*i];let p=v[2+2*i];if !(0..=32).contains(&d)||!(0..=1_000_000).contains(&p){return -1;}jobs.push((d,p));}jobs.sort_by(|a,b|b.1.cmp(&a.1));let mut slots=[false;33];let(mut chosen,mut profit)=(0i64,0i64);for(d,p)in jobs{for s in (1..=d as usize).rev(){if !slots[s]{slots[s]=true;chosen+=1;profit+=p;break;}}}chosen*32_000_001+profit}
